import{_ as a}from"./chunks/trace-detail.C3YICgeI.js";import{_ as t,o as s,c as n,a2 as i}from"./chunks/framework.CWdVbaJB.js";const k=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"title":"Architecture"},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md"}'),r={name:"concepts/architecture.md"};function o(d,e,l,p,c,h){return s(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>SHAVIRA is a self-hosted platform with a simple three-tier architecture. Your instrumented apps send trace data to the API (over the SDK ingest endpoint or OTLP), the API validates and persists it to PostgreSQL, and the React UI reads it back — with new traces pushed live over SSE.</p><p><img src="'+a+`" alt="SHAVIRA trace detail showing the span timeline, metadata, and per-span token and cost breakdown — the end result of the pipeline described on this page"></p><h2 id="system-diagram" tabindex="-1">System Diagram <a class="header-anchor" href="#system-diagram" aria-label="Permalink to &quot;System Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph &quot;Your Applications&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        APP1[Python App&lt;br/&gt;securitysdk]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        APP2[Node.js App&lt;br/&gt;@security-ai-agent/sdk]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        APP3[Any App&lt;br/&gt;OTel Collector]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph &quot;SHAVIRA Platform&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API[API Server&lt;br/&gt;Express 5 · Port 4000]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        WEB[Web UI&lt;br/&gt;React 19 · Port 4173]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        DB[(PostgreSQL 16&lt;br/&gt;Port 5432)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        BUS[Event Bus&lt;br/&gt;In-memory pub/sub]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    APP1 --&gt;|POST /api/ingest| API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    APP2 --&gt;|POST /api/ingest| API</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    APP3 --&gt;|POST /v1/traces&lt;br/&gt;OTLP/JSON| API</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API --&gt; DB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API --&gt; BUS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BUS --&gt;|SSE| WEB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WEB --&gt;|REST API| API</span></span></code></pre></div><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="api-server" tabindex="-1">API Server <a class="header-anchor" href="#api-server" aria-label="Permalink to &quot;API Server&quot;">​</a></h3><ul><li><strong>Framework:</strong> Express 5.1 on Node.js 24</li><li><strong>Language:</strong> TypeScript 5.9 (ESM)</li><li><strong>Validation:</strong> Zod 4.1 for all request/response schemas</li><li><strong>Database:</strong> Raw <code>pg</code> driver (no ORM)</li><li><strong>Auth:</strong> JWT (HS256, 8h access + 30d refresh) + API keys</li></ul><p>The API handles:</p><ul><li>Trace ingestion from SDKs and OTel collectors</li><li>REST API for the web UI</li><li>SSE streaming for real-time updates</li><li>Authentication and authorization</li><li>Background tasks (archive enforcement, cost recomputation)</li></ul><h3 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h3><ul><li><strong>Framework:</strong> React 19 with Vite 7.1</li><li><strong>Styling:</strong> Custom CSS with dark/light mode</li><li><strong>State:</strong> React hooks (no external state library)</li><li><strong>Build:</strong> Static bundle — no SSR</li></ul><p>The web UI is a single-page application served as static files. It communicates with the API server via REST and SSE.</p><h3 id="postgresql" tabindex="-1">PostgreSQL <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;PostgreSQL&quot;">​</a></h3><ul><li><strong>Version:</strong> 16</li><li><strong>Schema:</strong> Auto-bootstrapped on API startup</li><li><strong>Seeding:</strong> Demo data created when <code>BOOTSTRAP_DEFAULT_ADMIN=true</code></li><li><strong>Migrations:</strong> Append-safe — new tables/columns added with <code>IF NOT EXISTS</code></li></ul><h3 id="event-bus" tabindex="-1">Event Bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event Bus&quot;">​</a></h3><p>An in-memory publish/subscribe system for real-time trace streaming:</p><ul><li>Workspace-scoped channels</li><li>Max 5 concurrent SSE connections per workspace</li><li>30-second keepalive heartbeat</li><li>Best-effort delivery (no persistence)</li></ul><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><h3 id="ingest-flow" tabindex="-1">Ingest Flow <a class="header-anchor" href="#ingest-flow" aria-label="Permalink to &quot;Ingest Flow&quot;">​</a></h3><p>There are two ways in. The <strong>SDK path</strong> (<code>POST /api/ingest</code>) accepts SHAVIRA&#39;s own event envelope; the <strong>OTLP path</strong> (<code>POST /v1/traces</code>) accepts standard OpenTelemetry OTLP/JSON and converts spans into the same internal events. Both authenticate with a <code>shv_</code> API key that binds the data to a workspace (and optional project).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SDK/Collector → POST /api/ingest  (SdkEvent envelope)</span></span>
<span class="line"><span>             → POST /v1/traces   (OTLP/JSON → convertOtlpToIngestEvents)</span></span>
<span class="line"><span>    → Zod validation (sdkEventSchema / otlpTracesRequestSchema)</span></span>
<span class="line"><span>    → ingestEvent() — write to ingest_events (workspace-scoped JSONB payload)</span></span>
<span class="line"><span>    → Upsert finding      (if type = finding.upsert)</span></span>
<span class="line"><span>    → Compute cost        (if type = cost.record, or span.end carrying tokens)</span></span>
<span class="line"><span>    → Publish to event bus (best-effort, for live SSE)</span></span>
<span class="line"><span>    → 202 { accepted: true }   /   OTLP returns {}</span></span></code></pre></div><p><strong>OTLP attribute mapping.</strong> When you send OTLP spans, SHAVIRA reads well-known attributes so OTel data lands in the right place:</p><table tabindex="0"><thead><tr><th>OTLP attribute</th><th>Maps to</th></tr></thead><tbody><tr><td><code>service.name</code>, <code>deployment.environment</code> (resource)</td><td>Service / environment identity</td></tr><tr><td><code>shavira.session_id</code>, <code>shavira.user_id</code> (resource or span)</td><td>Session grouping and end-user attribution</td></tr><tr><td><code>gen_ai.system</code>, <code>gen_ai.request.model</code></td><td>Provider and model</td></tr><tr><td><code>gen_ai.usage.prompt_tokens</code>, <code>gen_ai.usage.completion_tokens</code></td><td>Token usage → cost</td></tr><tr><td>span <code>events[]</code> / <code>links[]</code></td><td>Stored on the event payload and surfaced in trace detail</td></tr></tbody></table><h3 id="query-flow" tabindex="-1">Query Flow <a class="header-anchor" href="#query-flow" aria-label="Permalink to &quot;Query Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Web UI → GET /api/traces (with filters)</span></span>
<span class="line"><span>    → Auth middleware (JWT cookie or API key)</span></span>
<span class="line"><span>    → RBAC check (admin sees all, member sees accessible projects)</span></span>
<span class="line"><span>    → PostgreSQL query with workspace_id scope</span></span>
<span class="line"><span>    → Return JSON array</span></span></code></pre></div><h3 id="sse-flow" tabindex="-1">SSE Flow <a class="header-anchor" href="#sse-flow" aria-label="Permalink to &quot;SSE Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Web UI → GET /api/traces/stream</span></span>
<span class="line"><span>    → Auth middleware</span></span>
<span class="line"><span>    → Subscribe to workspace channel on event bus</span></span>
<span class="line"><span>    → Stream trace.new and finding.new events</span></span>
<span class="line"><span>    → 30s keepalive heartbeat</span></span>
<span class="line"><span>    → Cleanup on disconnect</span></span></code></pre></div><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><p>The schema is bootstrapped automatically on API startup (append-safe <code>CREATE TABLE IF NOT EXISTS</code>). The core tables:</p><table tabindex="0"><thead><tr><th>Table</th><th>Holds</th></tr></thead><tbody><tr><td><code>workspaces</code></td><td>Top-level tenant boundary — everything is scoped to a workspace</td></tr><tr><td><code>users</code></td><td>Workspace accounts and roles (admin / member / viewer)</td></tr><tr><td><code>api_keys</code></td><td><code>shv_</code> ingest keys, bound to a workspace and optional project</td></tr><tr><td><code>projects</code> / <code>project_members</code></td><td>Projects and per-project RBAC grants (admin / analyst / viewer)</td></tr><tr><td><code>ingest_events</code></td><td>Raw ingested events (JSONB payload) — the source of truth for traces</td></tr><tr><td><code>traces</code></td><td>Trace records with event type, status, and metadata</td></tr><tr><td><code>apps</code></td><td>Instrumented services discovered from trace <code>service_name</code></td></tr><tr><td><code>detection_rules</code> / <code>detection_rule_versions</code></td><td>Sigma rules and their version history</td></tr><tr><td><code>detections</code> / <code>findings</code> / <code>finding_comments</code></td><td>Detection artifacts, findings, and triage discussion</td></tr><tr><td><code>model_endpoints</code> / <code>model_prices</code> / <code>model_aliases</code></td><td>Model routing config and synced pricing</td></tr><tr><td><code>cost_ledger</code></td><td>Resolved per-event cost for attribution roll-ups</td></tr><tr><td><code>audit_log</code> / <code>auth_log</code></td><td>Security and access audit trails</td></tr></tbody></table><p>Ingested events flow into <code>ingest_events</code>, are projected into <code>traces</code>, priced into <code>cost_ledger</code>, and — when a detection rule matches — produce <code>findings</code>. Every table carries a <code>workspace_id</code> so all reads can be tenant-scoped.</p><h2 id="dependency-graph" tabindex="-1">Dependency Graph <a class="header-anchor" href="#dependency-graph" aria-label="Permalink to &quot;Dependency Graph&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/shared    ← Type contracts (Zod schemas)</span></span>
<span class="line"><span>    ↑</span></span>
<span class="line"><span>packages/sdk       ← TypeScript SDK</span></span>
<span class="line"><span>    ↑</span></span>
<span class="line"><span>apps/api           ← API server</span></span>
<span class="line"><span>apps/web           ← Web frontend</span></span>
<span class="line"><span></span></span>
<span class="line"><span>packages/python-sdk ← Python SDK (independent, replicates contracts)</span></span></code></pre></div><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Language</td><td>TypeScript 5.9 (ESM), Python 3.x</td></tr><tr><td>Backend</td><td>Express 5.1, Node.js 24</td></tr><tr><td>Frontend</td><td>React 19, Vite 7.1</td></tr><tr><td>Database</td><td>PostgreSQL 16</td></tr><tr><td>Validation</td><td>Zod 4.1</td></tr><tr><td>Testing</td><td>Vitest 3.2, Playwright</td></tr><tr><td>Containers</td><td>Docker, multi-stage builds</td></tr></tbody></table>`,36)])])}const b=t(r,[["render",o]]);export{k as __pageData,b as default};
